package studio.jiayu.neoagent;
import android.app.Activity;import org.json.*;import java.io.*;import java.util.*;
final class RoutineContracts {
 static void run(Activity a){Vault vault=new Vault(a);String before="";JSONObject out=new JSONObject();int passed=0;try{before=vault.get(RoutineAccess.KEY);vault.remove(RoutineAccess.KEY);RoutineAccess grant=new RoutineAccess(a);Config c=new Config();c.endpoint="https://example.invalid/v1";c.key="LOCAL_TEST_ONLY";c.vision=false;List<String> owned=Arrays.asList(a.getPackageName());if(grant.allows(c,owned))throw new Exception("missing grant accepted");passed++;grant.approve(c,owned);if(!new RoutineAccess(a).allows(c,owned))throw new Exception("persisted grant lost");passed++;c.model="changed-model";if(!grant.allows(c,owned))throw new Exception("same recipient model change reasks");passed++;c.vision=true;if(grant.allows(c,owned))throw new Exception("vision scope expanded");passed++;c.vision=false;c.endpoint="https://other.invalid/v1";if(grant.allows(c,owned))throw new Exception("recipient changed");passed++;c.endpoint="https://example.invalid/other";if(grant.allows(c,owned))throw new Exception("path changed");passed++;c.endpoint="https://example.invalid/v1";if(grant.allows(c,Arrays.asList("example.unselected")))throw new Exception("unselected app granted");passed++;if(grant.allows(c,Collections.emptyList()))throw new Exception("empty plan granted");passed++;String raw=vault.get(RoutineAccess.KEY);if(raw.contains(c.key)||raw.contains("allowOrderApproval"))throw new Exception("credential or payment grant persisted");passed++;c.vision=true;grant.approve(c,owned);c.vision=false;grant.approve(c,owned);c.vision=true;if(!grant.allows(c,owned))throw new Exception("existing screen grant overwritten");passed++;c.endpoint="https://other.invalid/v1";grant.approve(c,owned);c.endpoint="https://example.invalid/v1";if(!new RoutineAccess(a).allows(c,owned))throw new Exception("previous recipient grant overwritten");passed++;grant.approve(c,owned);vault.remove(RoutineAccess.KEY);if(grant.allows(c,owned))throw new Exception("revoked grant accepted");passed++;out.put("success",true).put("passed",passed).put("network_calls",0).put("gestures",0);}catch(Exception e){try{out.put("success",false).put("passed",passed).put("failure",e.getMessage());}catch(Exception ignored){}}finally{try{if(before.isEmpty())vault.remove(RoutineAccess.KEY);else vault.put(RoutineAccess.KEY,before);try(FileOutputStream f=a.openFileOutput("routine-contracts.json",0)){f.write(out.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}a.finish();}}
}
